VRT_L("tle-d-svt-r32",{"duree":20,"titre":"Structure du tissu nerveux","accroche":"Des milliards de cellules connectées.","intro":"Le tissu nerveux réunit les neurones et leurs cellules de soutien.","objectifs":["décrire un neurone","distinguer substance grise et blanche","préparer une dissection"],"parties":[{"t":"Le neurone","html":"<div class='def'><b>Définition</b>Le <strong>neurone</strong> est la cellule nerveuse. Il comprend un corps cellulaire, des dendrites et un axone.</div>"},{"t":"Substances grise et blanche","verrou":true},{"t":"Le nerf","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":32,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"En TP à Bamenda, un groupe prépare la dissection de l'encéphale d'un petit mammifère.","tache":"Cite trois règles à respecter."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r33",{"duree":20,"titre":"Réflexes innés : les éléments du réflexe médullaire","accroche":"La main se retire avant la douleur.","intro":"Un réflexe est une réponse involontaire, rapide et stéréotypée.","objectifs":["définir le réflexe","nommer les éléments de l'arc réflexe","exploiter une expérience"],"parties":[{"t":"L'arc réflexe","html":"<div class='def'><b>Définition</b>L'<strong>arc réflexe</strong> comprend un récepteur, une voie sensitive, un centre nerveux, une voie motrice et un effecteur.</div>"},{"t":"Le réflexe médullaire","verrou":true},{"t":"Les expériences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":33,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"En cuisine à Ebolowa, une fille retire brusquement sa main d'une marmite très chaude.","tache":"Présente le trajet du message."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r34",{"duree":20,"titre":"Le réflexe myotatique","accroche":"Le médecin frappe le genou, la jambe bouge.","intro":"L'étirement d'un muscle provoque sa contraction : ce réflexe assure la posture.","objectifs":["décrire le réflexe myotatique","expliquer son caractère monosynaptique","préciser son importance"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>réflexe myotatique</strong> est la contraction d'un muscle en réponse à son propre étirement.</div>"},{"t":"Le circuit","verrou":true},{"t":"Importance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":34,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Au dispensaire de Sangmélima, une infirmière teste le réflexe rotulien d'un patient.","tache":"Explique l'intérêt de ce test."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r35",{"duree":20,"titre":"Réflexes acquis ou conditionnels","accroche":"Le chien salive au son de la cloche.","intro":"Un apprentissage peut associer un stimulus neutre à une réponse réflexe.","objectifs":["décrire l'expérience de Pavlov","distinguer réflexe inné et acquis","donner des applications"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>réflexe conditionnel</strong> est une réponse acquise à la suite de l'association répétée d'un stimulus neutre et d'un stimulus absolu.</div>"},{"t":"Conditions","verrou":true},{"t":"Applications","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":35,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Un élève de Kribi se réveille chaque matin juste avant la sonnerie de son réveil.","tache":"Propose une explication prudente."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r36",{"duree":20,"titre":"Intégration : les réflexes au service de la sécurité","accroche":"Un réflexe protège, l'alcool le retarde.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Un <strong>réflexe</strong> repose sur un circuit dont le fonctionnement peut être perturbé par des substances.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":36,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Un conducteur de moto-taxi de Douala affirme qu'il freine aussi vite après avoir bu.","tache":"Montre-lui que l'alcool augmente le risque d'accident."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r37",{"duree":20,"titre":"Le potentiel de repos","accroche":"Une pile électrique dans chaque neurone.","intro":"Au repos, l'intérieur de la fibre nerveuse est négatif par rapport à l'extérieur.","objectifs":["définir le potentiel de repos","expliquer son origine ionique","lire un enregistrement"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>potentiel de repos</strong> est la différence de potentiel d'environ −70 mV entre l'intérieur et l'extérieur d'une fibre au repos.</div>"},{"t":"Origine","html":"<p>La membrane est plus perméable au K⁺. La pompe Na⁺/K⁺ maintient les différences de concentration.</p>","retenir":"Intérieur négatif : environ −70 mV.","labo":{"type":"potentiel"}},{"t":"Mesure","html":"<p>Une microélectrode intracellulaire reliée à un oscilloscope révèle la différence de potentiel.</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Au repos, l'intérieur de la fibre est :</p><ol type='a'><li>positif</li><li>négatif</li><li>neutre</li></ol><details><summary>Voir la réponse</summary><p><strong>négatif</strong>. −70 mV.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Quelle est la valeur approchée du potentiel de repos ?</p><details><summary>Voir la réponse</summary><p>(Réponse : −70 mV.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Comprendre et préserver le système nerveux et les défenses de l'organisme.</p><p><strong>Situation.</strong> En TP, une microélectrode enfoncée dans un axone affiche −70 mV. On place l'axone dans une solution contenant du cyanure, qui bloque la production d'ATP : la valeur diminue lentement vers 0 mV.</p><p><strong>Consigne 1.</strong> Explique l'origine du potentiel de repos.</p><p><strong>Consigne 2.</strong> Interprète l'effet du cyanure.</p><details><summary>Voir une réponse attendue</summary><p>La membrane est polarisée : plus de K⁺ à l'intérieur, plus de Na⁺ à l'extérieur, et la membrane au repos est surtout perméable au K⁺, qui sort. La pompe Na⁺/K⁺, qui consomme de l'ATP, maintient ces différences. Sans ATP, la pompe s'arrête : les ions diffusent, les concentrations s'égalisent et le potentiel s'annule progressivement.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans l'analyse."}],"revision":["−70 mV.","K⁺.","Pompe Na⁺/K⁺."],"exo":"<p>Quelle est la valeur approchée du potentiel de repos ? <em>(Réponse : −70 mV.)</em></p>","quiz":[{"q":"Au repos, l'intérieur de la fibre est :","r":["positif","négatif","neutre"],"b":1,"e":"−70 mV."},{"q":"La membrane au repos est surtout perméable à :","r":["K⁺","Na⁺","l'ADN"],"b":0,"e":"Canaux de fuite."},{"q":"La pompe Na⁺/K⁺ utilise :","r":["le CO₂","la lumière","l'ATP"],"b":2,"e":"Transport actif."},{"q":"Le potentiel de repos se mesure avec :","r":["un thermomètre","une microélectrode","une balance"],"b":1,"e":"Oscilloscope."}],"c":"Tle D","m":"svt","rang":37,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Dans un TP à Bafoussam, l'oscilloscope affiche −70 mV dès l'entrée de l'électrode dans la fibre.","tache":"Interprète ce résultat."},"gratuit":true});
VRT_L("tle-d-svt-r38",{"duree":20,"titre":"Le potentiel d'action","accroche":"Tout ou rien : le neurone ne chuchote pas.","intro":"Une stimulation suffisante provoque une inversion brève du potentiel de membrane.","objectifs":["décrire le potentiel d'action","expliquer les mouvements d'ions","appliquer la loi du tout ou rien"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>potentiel d'action</strong> est une inversion brève et propagée de la polarité membranaire, déclenchée à partir d'un seuil.</div>"},{"t":"Les phases","verrou":true},{"t":"Propriétés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":38,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Un élève de Mbalmayo augmente l'intensité d'un stimulus et croit que chaque potentiel d'action devient plus grand.","tache":"Corrige son idée."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r39",{"duree":20,"titre":"Naissance du potentiel d'action","accroche":"De la lumière ou d'une pression naît un message nerveux.","intro":"Les récepteurs sensoriels transforment un stimulus en message nerveux.","objectifs":["définir le potentiel de récepteur","expliquer la transduction","préciser la zone d'initiation"],"parties":[{"t":"Le récepteur","html":"<div class='def'><b>Définition</b>La <strong>transduction</strong> est la transformation d'un stimulus en potentiel de récepteur dans un récepteur sensoriel.</div>"},{"t":"Le potentiel de récepteur","verrou":true},{"t":"Au niveau du neurone","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":39,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Une couturière de Garoua sent la piqûre d'une aiguille au bout du doigt.","tache":"Explique la naissance du message."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r40",{"duree":20,"titre":"Propagation du potentiel d'action","accroche":"Jusqu'à plus de 100 m/s sur certaines fibres.","intro":"Le potentiel d'action se propage de proche en proche ou de nœud en nœud.","objectifs":["comparer les conductions","calculer une vitesse","expliquer le rôle de la myéline"],"parties":[{"t":"Les modes de conduction","html":"<div class='def'><b>Définition</b>Dans une fibre sans myéline, la conduction est <strong>de proche en proche</strong>. Dans une fibre myélinisée, elle est <strong>saltatoire</strong>, d'un nœud de Ranvier à l'autre.</div>"},{"t":"La vitesse","verrou":true},{"t":"La période réfractaire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":40,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Un enregistrement à deux électrodes sépare de 4 cm un même potentiel d'action, avec un retard de 1 ms.","tache":"Calcule la vitesse."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r41",{"duree":20,"titre":"Intégration : le message nerveux dans la vie courante","accroche":"Le toucher, la douleur, le geste.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Un <strong>message nerveux</strong> est une suite de potentiels d'action.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":41,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"Un chauffeur blessé à l'avant-bras à Tiko ne sent plus ses doigts.","tache":"Explique cette perte de sensibilité."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r42",{"duree":20,"titre":"La synapse : structure","accroche":"Entre deux neurones, un espace.","intro":"La synapse est la zone de communication entre deux cellules excitables.","objectifs":["décrire une synapse","nommer les éléments","distinguer les types"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>synapse</strong> est une zone de jonction fonctionnelle entre un neurone et une autre cellule.</div>"},{"t":"Éléments","verrou":true},{"t":"Types","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":42,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"En TP à Yaoundé, un élève observe une électronographie de synapse.","tache":"Liste les éléments à légender."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r43",{"duree":20,"titre":"La synapse : fonctionnement","accroche":"Un message électrique devient chimique, puis redevient électrique.","intro":"La transmission synaptique met en jeu un neurotransmetteur.","objectifs":["décrire les étapes","expliquer le rôle du Ca²⁺","distinguer PPSE et PPSI"],"parties":[{"t":"Les étapes","html":"<div class='def'><b>Définition</b>La <strong>transmission synaptique</strong> : l'arrivée du potentiel d'action provoque l'entrée de Ca²⁺, l'exocytose du neurotransmetteur et sa fixation sur des récepteurs postsynaptiques.</div>"},{"t":"PPSE et PPSI","verrou":true},{"t":"Fin du message","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":43,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"On stimule un neurone présynaptique et on enregistre : potentiel d'action présynaptique à t = 0 ; dépolarisation de la cellule postsynaptique à t = 0,5 ms. Sur une même fibre sans synapse, le message parcourt la même distance en 0,01 ms.","tache":"Explique ce délai."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r44",{"duree":20,"titre":"L'intégration neuronale","accroche":"Un neurone additionne avant de répondre.","intro":"Un neurone reçoit de nombreux messages excitateurs et inhibiteurs.","objectifs":["définir la sommation","distinguer spatiale et temporelle","prévoir une réponse"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>intégration neuronale</strong> est l'addition, au niveau du neurone postsynaptique, des potentiels reçus.</div>"},{"t":"Les sommations","verrou":true},{"t":"Le résultat","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":44,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"On enregistre un neurone moteur (repos −70 mV, seuil −55 mV). Un PPSE isolé le porte à −64 mV ; deux PPSE simultanés venant de deux synapses, à −58 mV ; trois PPSE simultanés déclenchent un potentiel d'action.","tache":"Interprète ces résultats."},"verrou":true,"nq":4,"labo":true});
VRT_L("tle-d-svt-r45",{"duree":20,"titre":"Substances et transmission synaptique","accroche":"Tramadol, alcool, cannabis : des effets sur la synapse.","intro":"Certaines substances modifient le fonctionnement des synapses et créent une dépendance.","objectifs":["expliquer le mode d'action","citer des substances","prévenir les addictions"],"parties":[{"t":"Les modes d'action","html":"<div class='def'><b>Définition</b>Une substance peut <strong>imiter</strong>, <strong>bloquer</strong> ou <strong>prolonger</strong> l'action d'un neurotransmetteur.</div>"},{"t":"Exemples","verrou":true},{"t":"Dépendance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":45,"apc":{"module":"Système nerveux et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver le système nerveux et les défenses de l'organisme","situation":"À Maroua, des jeunes consomment du tramadol pour tenir pendant les travaux pénibles.","tache":"Rédige un message de prévention."},"verrou":true,"nq":4,"labo":true});
