VRT_L("tle-d-svt-r92",{"duree":20,"titre":"Insectes comestibles et lutte biologique","accroche":"Termites, larves de palmier et miel.","intro":"Des insectes offrent des ressources alimentaires, thérapeutiques et agricoles.","objectifs":["citer des insectes utiles","préciser leur intérêt","définir la lutte biologique"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>L'<strong>entomophagie</strong> est la consommation d'insectes. La <strong>lutte biologique</strong> utilise des êtres vivants pour limiter un ravageur.</div>"},{"t":"Ressources","verrou":true},{"t":"Lutte biologique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle D","m":"svt","rang":92,"apc":{"module":"Terre, évolution et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"À Mbalmayo, des larves de palmier sont vendues au marché.","tache":"Présente un intérêt et une précaution."},"verrou":true,"nq":4,"labo":true});
